// Registered with FirebaseMessaging.onMessage and onBackgroundMessage
Future<void> onPush(RemoteMessage message) async {
  final id = message.data['appointmentId'] as String;
  final time = DateTime.parse(message.data['time'] as String);
  // The push IS the update: miss it and the app stays wrong
  await db.saveAppointmentTime(id, time);
}

// The push only says "something changed"
Future<void> onPush(RemoteMessage message) => pullChanges();

// Also called on app start and on every resume
Future<void> pullChanges() async {
  final since = await db.lastSyncToken();
  final changes = await api.changesSince(since);
  // Applying the same page twice changes nothing
  await db.applyChanges(changes.items, changes.nextToken);
}
